import{_ as o,a0 as i,w as s,s as d,ao as n,I as r,x as e,a1 as a,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"開源代碼評審的十個通用步驟 | LCTT x X-CMD","titleTemplate":false,"description":"開源代碼評審的十個通用步驟 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"開源代碼評審的十個通用步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"開源代碼評審的十個通用步驟 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221031.1 ⭐️⭐️⭐️ 10 universal steps for open source code review","title":"開源代碼評審的十個通用步驟","tag":"202301","desc":""},"relativePath":"202301/20221031.1 ⭐️⭐️⭐️ 10 universal steps for open source code review.md","filePath":"[post].md"}'),u={name:"202301/20221031.1 ⭐️⭐️⭐️ 10 universal steps for open source code review.md"};function f(m,t,b,T,x,h){const l=i("Link");return s(),d("div",null,[t[29]||(t[29]=n('<h1 id="開源代碼評審的十個通用步驟" tabindex="-1">開源代碼評審的十個通用步驟 <a class="header-anchor" href="#開源代碼評審的十個通用步驟" aria-label="Permalink to “開源代碼評審的十個通用步驟”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/29/140840wsbypukbubp69buv.jpg" alt=""></p><blockquote><p>只要你遵循這些通用流程，代碼評審並不可怕。</p></blockquote><p>你是否需要在你還沒有完全理解整個項目時就對代碼進行評審？抑或你避開了評審，以免讓你看起來不知道如何進行。</p><p>本篇文章想要告訴你一個更好的方法。<ruby>代碼評審<rt>code review</rt></ruby> 並不需要你知道所有事情。實際上，就我個人經驗而言，這種情況非常普遍。</p><p>我還記得作為實習生加入 <ruby>紅帽<rt>Red Hat</rt></ruby> 的時候，被要求參與代碼評審。我們當時採取的是 +1 或 -1 的投票系統，而我在一開始的時候常常躊躇於該如何評審。我發現我會問自己，如果我對於一處改動給予了 +1，而別人卻投了 -1，我是不是看起來很蠢？</p><p>如果你對一處改動投了 +1，而別人投了 -1，這又意味着什麼呢？答案是不意味任何事！你可能只是漏掉了一處別人注意到的細節。這不意味着世界末日。這也是為什麼我們會用投票系統。正如同所有開源項目一樣，代碼合併是一項協同工作。</p><p>最近，我接到了太多的代碼評審工作，以至於我幾乎做不過來。我同時也注意到，參與評審的貢獻者數量正在穩步減少。</p><p>出於這個原因，我想要寫一篇文章闡述我對代碼評審的個人觀點。在這篇文章裏，我會分享一些訣竅與技巧。我將會向你展示幾個用來問自己的問題，以及在評審代碼時需要注意的一些地方。</p><h3 id="代碼評審的目的是什麼" tabindex="-1">代碼評審的目的是什麼？ <a class="header-anchor" href="#代碼評審的目的是什麼" aria-label="Permalink to “代碼評審的目的是什麼？”">​</a></h3><p>你是否曾寫過一個非常簡單的補丁？你認為它是如此微不足道，不需要審查。或許你直接就合併了它。直到晚些時候，你意識到你犯了個錯誤，一個明顯的或是愚蠢的錯誤，比如錯誤的縮進，比如幾行重複的代碼而不是調用函數（是的，這些都是經驗之談！）。</p><p>如果有其他人來審查代碼，就會發現這些東西。</p><p>代碼評審的一個目的便是為你帶來一雙新的眼睛，從新的視角看待你要嘗試解決的問題。這種新的背景也正是為什麼代碼評審至關重要。</p><p>你可能認為你必須是一個語言專家，才能審查別人的代碼、項目，或兩者。讓我來告訴你一個所有代碼評審者都想跟你説的秘密吧：大錯特錯！你並不需要完全理解該項目或者編程語言，就可以為一個改動提供全新的視角。下面，我將向你展示代碼評審的通用流程。</p><h3 id="代碼評審的通用流程" tabindex="-1">代碼評審的通用流程 <a class="header-anchor" href="#代碼評審的通用流程" aria-label="Permalink to “代碼評審的通用流程”">​</a></h3><p>這是我的代碼評審流程，拆分成了幾個要點。這個流程包含了我會問自己的一些問題，以幫助我專注於代碼的變化以及其後果。你不需要嚴格依照這個順序來進行評審。如果有任何原因導致你無法執行其中的某一步，跳過那一步就好。</p><h4 id="_1、理解改動-它想要解決的問題-以及為什麼要這麼做" tabindex="-1">1、理解改動，它想要解決的問題，以及為什麼要這麼做 <a class="header-anchor" href="#_1、理解改動-它想要解決的問題-以及為什麼要這麼做" aria-label="Permalink to “1、理解改動，它想要解決的問題，以及為什麼要這麼做”">​</a></h4><p>為什麼需要改動的解釋以及任何相關背景都應該被放在 <ruby>提交<rt>commit</rt></ruby> 信息裏。如果沒有，請要求提供，並請投 -1 直到相關信息被提供。</p><p>改動想解決的問題需要被解決嗎？它是項目應當關注的問題，還是與項目完全無關？</p><h4 id="_2、你會如何實現解決方案-它會不一樣嗎" tabindex="-1">2、你會如何實現解決方案？它會不一樣嗎？ <a class="header-anchor" href="#_2、你會如何實現解決方案-它會不一樣嗎" aria-label="Permalink to “2、你會如何實現解決方案？它會不一樣嗎？”">​</a></h4><p>在這個時候，你應該已經知道代碼改動是為了什麼。換做是你會怎麼做？在進一步對改動進行細節評審前，先思考這個問題。如果你想出了一個不一樣的解決方案，並且你認為你的方案更好，在評審中提出來。你不需要投 -1；去問問作者為什麼沒有往那個方向走，看看這次討論會把你們帶向何方。</p><h4 id="_3、運行有改動和沒有改動的代碼" tabindex="-1">3、運行有改動和沒有改動的代碼 <a class="header-anchor" href="#_3、運行有改動和沒有改動的代碼" aria-label="Permalink to “3、運行有改動和沒有改動的代碼”">​</a></h4><p>我通常會在代碼中設置幾個斷點，運行代碼並檢查新代碼是如何與其餘部分互動的。</p><p>如果你無法運行整個代碼，試着將帶有新代碼的函數複製到一個新的本地文件，模擬輸入數據，然後運行。這在你不知道怎麼運行整個項目，或者無法接觸到運行所需的特殊環境時很有幫助。</p><h4 id="_4、新代碼會破壞任何東西嗎" tabindex="-1">4、新代碼會破壞任何東西嗎？ <a class="header-anchor" href="#_4、新代碼會破壞任何東西嗎" aria-label="Permalink to “4、新代碼會破壞任何東西嗎？”">​</a></h4><p>我是説，任何東西。想一想可能的後果。</p><p>以一個新的命令列選項為例，它會總是被目標所接受嗎？</p><p>是否存在這樣一種情況，使得新選項無法被接受或是會與其他東西起衝突？</p><p>或許新代碼是導入了新的東西。那麼這個新的庫，以及可能的新的依賴關係，能夠在老版本或者項目的運行系統中被找到嗎？</p><p>安全方面呢？新的依賴足夠安全嗎？你至少可以在網上快速地搜索一下。還有，注意一下控制台日誌裏的警告。有的時候在同一個庫裏也可以找到更安全的函數。</p><h4 id="_5、新代碼是否有效" tabindex="-1">5、新代碼是否有效？ <a class="header-anchor" href="#_5、新代碼是否有效" aria-label="Permalink to “5、新代碼是否有效？”">​</a></h4><p>你剛剛確認了被提出的解決方案大概是正確的。現在該檢查代碼本身了。你需要關注代碼的有效性和必要性。</p><p>檢查新代碼的風格。它與項目的代碼風格相匹配嗎？任何開源項目都（應該）有一份文檔告知（新）貢獻者項目所遵循的風格和優秀實踐。</p>',33)),r("p",null,[t[1]||(t[1]=e("比如説，OpenStack 社區的所有項目都有一份 HACKING.rst 文件。你經常也能找到一份",-1)),a(l,{href:"https://docs.openstack.org/tempest/latest/contributor/contributing.html"},{default:p(()=>[...t[0]||(t[0]=[e("新貢獻者指南",-1)])]),_:1}),t[2]||(t[2]=e("包含所有必須知道的信息。",-1))]),t[30]||(t[30]=r("h4",{id:"_6、確認所有新增的變量和導入都被使用",tabindex:"-1"},[e("6、確認所有新增的變量和導入都被使用 "),r("a",{class:"header-anchor",href:"#_6、確認所有新增的變量和導入都被使用","aria-label":"Permalink to “6、確認所有新增的變量和導入都被使用”"},"​")],-1)),t[31]||(t[31]=r("p",null,"你正在評審的代碼常常已經過多次迭代，有的時候代碼的最終版本與初始版已迥然不同。所以我們很容易忘記一些在歷史版本中加入的變量與引用。自動化檢測通常會用到 lint 工具，類似 Python 中的 [flake8][12]。",-1)),r("p",null,[t[4]||(t[4]=e("（LCTT 譯註：",-1)),a(l,{href:"https://codedocs.org/what-is/lint-software"},{default:p(()=>[...t[3]||(t[3]=[e("lint",-1)])]),_:1}),t[5]||(t[5]=e(" 指編程中用來發現代碼潛在錯誤和約束代碼風格的工具，起源於 C 語言編程中的靜態分析工具 ",-1)),t[6]||(t[6]=r("code",null,"lint",-1)),t[7]||(t[7]=e("。“lint” 本意為衣服上積累的絨毛與灰塵，“lint” 的取名寓意則在於捕捉編程時產生的“絨毛與灰塵”）",-1))]),t[32]||(t[32]=n('<p>（LCTT 校注：我建議，“Lint” 工具可以翻譯為 “代碼清理” 或 “代碼清潔” 工具。）</p><p>你可以在不聲明新變量的情況下重寫代碼嗎？通常情況下你可以，但問題是這樣是否更好。這會帶來什麼益處嗎？我們的目標不是要創造儘可能多的單行代碼，而是寫出高效且易讀的代碼。</p><h4 id="_7、新的函數和方法是否必要" tabindex="-1">7、新的函數和方法是否必要？ <a class="header-anchor" href="#_7、新的函數和方法是否必要" aria-label="Permalink to “7、新的函數和方法是否必要？”">​</a></h4><p>項目裏的別的地方是否存在可以被複用的功能類似的函數？確保避免重新發明輪子以及重新實現已經被定義的邏輯永遠都是值得的。</p><h4 id="_8、有單元測試嗎" tabindex="-1">8、有單元測試嗎？ <a class="header-anchor" href="#_8、有單元測試嗎" aria-label="Permalink to “8、有單元測試嗎？”">​</a></h4><p>如果補丁增加了新的函數或者在函數內添加了新的邏輯，它也應該附帶對應的單元測試。新函數的作者總是比別人更適合寫該函數的單元測試。</p><h4 id="_9-驗證重構" tabindex="-1">9. 驗證重構 <a class="header-anchor" href="#_9-驗證重構" aria-label="Permalink to “9. 驗證重構”">​</a></h4><p>如果這次提交對現有代碼進行了重構（它可能重命名了某個變量，或者是改變了的變量的作用域，或者是通過加減參數來改變函數的足跡，又或者是刪去了某個東西），問一問你自己：</p><ul><li>這個可以被刪除嗎？它會影響到穩定分支嗎？</li><li>所有出現的地方都刪掉了嗎？</li></ul>',9)),r("p",null,[t[9]||(t[9]=e("你可以利用 ",-1)),a(l,{href:"https://opensource.com/downloads/grep-cheat-sheet"},{default:p(()=>[...t[8]||(t[8]=[e("grep 命令",-1)])]),_:1}),t[10]||(t[10]=e(" 來查找。你不會相信有多少次我投 -1 就是因為這個。這是一個任何人都會犯的簡單錯誤，也正因如此任何人都可以發現它。",-1))]),t[33]||(t[33]=r("p",null,"提交的所有者很容易忽略這些事情，這完全可以理解。我也犯過很多次這種錯誤。我最終發現問題的根源在於我太急於提出評審，以至於我忘記了對倉庫進行整體檢查。",-1)),t[34]||(t[34]=r("p",null,"除了對項目倉庫的檢查外，檢查其他代碼用户也十分必要。如果有別的項目導入了這個項目，它們可能也需要進行重構。在 OpenStack 社區中，我們有對應的工具來查詢別的社區項目。",-1)),t[35]||(t[35]=r("h4",{id:"_10、項目文檔是否需要做出更改",tabindex:"-1"},[e("10、項目文檔是否需要做出更改？ "),r("a",{class:"header-anchor",href:"#_10、項目文檔是否需要做出更改","aria-label":"Permalink to “10、項目文檔是否需要做出更改？”"},"​")],-1)),r("p",null,[t[12]||(t[12]=e("你可以再一次使用 ",-1)),a(l,{href:"https://www.redhat.com/sysadmin/how-to-use-grep"},{default:p(()=>[...t[11]||(t[11]=[e("grep 命令",-1)])]),_:1}),t[13]||(t[13]=e(" 來檢查在項目文檔中是否提到了相關的代碼改動。用常識來判斷這次改動是否需要被收入文檔以告知最終用户，還是隻是一個不會影響用户體驗的內部變化。",-1))]),t[36]||(t[36]=r("h4",{id:"額外提示-考慮周到",tabindex:"-1"},[e("額外提示：考慮周到 "),r("a",{class:"header-anchor",href:"#額外提示-考慮周到","aria-label":"Permalink to “額外提示：考慮周到”"},"​")],-1)),t[37]||(t[37]=r("p",null,"當你在評審完新代碼後提出建議或評論時，要考慮周到，反饋準確，描述詳盡。如果有你不理解的地方就發出提問。如果你認為代碼存在錯誤，解釋你的理由。記住，如果作者不知道什麼地方出了問題，他們就無法修復它。",-1)),t[38]||(t[38]=r("h3",{id:"最後幾句",tabindex:"-1"},[e("最後幾句 "),r("a",{class:"header-anchor",href:"#最後幾句","aria-label":"Permalink to “最後幾句”"},"​")],-1)),t[39]||(t[39]=r("p",null,"唯一的壞評審是沒有評審。通過評審和投票，你提供了你的觀點併為此投票。沒有人指望你來做出最終決定（除非你是核心維護者），但是投票系統允許你提供你的觀點和意見。相信我，補丁所有者會很高興你這麼做了的。",-1)),t[40]||(t[40]=r("p",null,"你能想到別的要點來給出好的評審嗎？你是否有我不知道的特殊技巧？在評論中分享它們吧！",-1)),t[41]||(t[41]=r("hr",null,null,-1)),r("p",null,[t[15]||(t[15]=e("via: ",-1)),a(l,{href:"https://opensource.com/article/22/10/code-review"},{default:p(()=>[...t[14]||(t[14]=[e("https://opensource.com/article/22/10/code-review",-1)])]),_:1})]),r("p",null,[t[20]||(t[20]=e("作者：",-1)),a(l,{href:"https://opensource.com/users/martin-kopec"},{default:p(()=>[...t[16]||(t[16]=[e("Martin Kopec",-1)])]),_:1}),t[21]||(t[21]=e(" 選題：",-1)),a(l,{href:"https://github.com/lkxed"},{default:p(()=>[...t[17]||(t[17]=[e("lkxed",-1)])]),_:1}),t[22]||(t[22]=e(" 譯者：",-1)),a(l,{href:"https://github.com/yzuowei"},{default:p(()=>[...t[18]||(t[18]=[e("yzuowei",-1)])]),_:1}),t[23]||(t[23]=e(" 校對：",-1)),a(l,{href:"https://github.com/wxy"},{default:p(()=>[...t[19]||(t[19]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=e("本文由 ",-1)),a(l,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[24]||(t[24]=[e("LCTT",-1)])]),_:1}),t[27]||(t[27]=e(" 原創編譯，",-1)),a(l,{href:"https://linux.cn/"},{default:p(()=>[...t[25]||(t[25]=[e("Linux中國",-1)])]),_:1}),t[28]||(t[28]=e(" 榮譽推出",-1))])])}const w=o(u,[["render",f]]);export{C as __pageData,w as default};
